import { isRecord } from "./is-record.js";
const MODEL_ID = /^[a-z0-9][a-z0-9.-]{0,127}$/;
const LEVELS = new Set(["low", "medium", "high", "xhigh"]);
export const MODEL_CONFIG_REQUIRES_DRY_RUN = "invalid argument: modelConfig requires dryRun";
export class InvalidModelConfigError extends Error {
    constructor(message) {
        super(message);
        this.name = "InvalidModelConfigError";
    }
}
function invalid(message) {
    throw new InvalidModelConfigError(message);
}
function setting(value, where) {
    if (!isRecord(value))
        invalid(`invalid argument: ${where}.id is not a model id`);
    const id = value.id;
    if (typeof id !== "string" || !MODEL_ID.test(id)) {
        invalid(`invalid argument: ${where}.id is not a model id`);
    }
    const rawParams = value.params;
    if (!Array.isArray(rawParams))
        invalid(`invalid argument: ${where} requires params`);
    const effortId = id.includes("gpt") ? "reasoning" : "effort";
    const params = [];
    const seen = new Set();
    for (const param of rawParams) {
        if (!isRecord(param))
            invalid(`invalid argument: ${where} param "" is not allowed`);
        const paramId = typeof param.id === "string" ? param.id : "";
        const paramValue = typeof param.value === "string" ? param.value : "";
        if (paramId === "" ||
            paramValue === "" ||
            (paramId !== effortId && paramId !== "fast") ||
            seen.has(paramId)) {
            invalid(`invalid argument: ${where} param ${JSON.stringify(paramId)} is not allowed`);
        }
        const valueOk = paramId === "fast" ? paramValue === "true" || paramValue === "false" : LEVELS.has(paramValue);
        if (!valueOk)
            invalid(`invalid argument: ${where} param ${JSON.stringify(paramId)} bad value`);
        seen.add(paramId);
        params.push({ id: paramId, value: paramValue });
    }
    if (!seen.has(effortId) || !seen.has("fast")) {
        invalid(`invalid argument: ${where} requires params ${effortId} and fast`);
    }
    return { id, params };
}
export function modelConfigForDryRun(modelConfig, dryRun) {
    if (modelConfig === undefined)
        return undefined;
    if (dryRun !== true)
        invalid(MODEL_CONFIG_REQUIRES_DRY_RUN);
    if (!isRecord(modelConfig)) {
        invalid("invalid argument: modelConfig must be { model, fallbacks? }");
    }
    const model = setting(modelConfig.model, "modelConfig.model");
    const fallbacks = modelConfig.fallbacks;
    if (fallbacks === undefined)
        return { model, fallbacks: [] };
    if (!Array.isArray(fallbacks))
        invalid("invalid argument: modelConfig.fallbacks must be an array");
    return {
        model,
        fallbacks: fallbacks.map((item, i) => setting(item, `modelConfig.fallbacks[${i}]`)),
    };
}
